import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String tenant = req.getParameter("tenant");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("^(json|xml|csv)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // Tenant isolation check - defense in depth
        String sessionTenant = (String) req.getSession().getAttribute("tenant_id");
        if (tenant != null && !tenant.equals(sessionTenant)) {
            log.warning("Tenant mismatch: requested=" + tenant + " session=" + sessionTenant);
            resp.sendError(403, "Tenant mismatch");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query with tenant filter
            String query = "SELECT r.id, r.title, r.content, r.created_at " +
                          "FROM reports r " +
                          "WHERE r.tenant_id = '" + sessionTenant + "' " +
                          "AND r.id = " + reportId;

            log.info("Executing report query for tenant: " + sessionTenant);
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");
            if (rs.next()) {
                out.print("\"id\":" + rs.getInt("id") + ",");
                out.print("\"title\":\"" + escapeJson(rs.getString("title")) + "\",");
                out.print("\"content\":\"" + escapeJson(rs.getString("content")) + "\",");
                out.print("\"created_at\":\"" + rs.getString("created_at") + "\"");
            }
            out.print("}");
            out.flush();
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Delegate to GET for backward compatibility
        doGet(req, resp);
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
